/******************************************************************
  Standalone Arduino Nano project
  Light intensity + temperature + humidity

  No external DHT library required.

  Connections:
  D2-D8  -> Seven segment display (a-g)
  D9     -> Mode button (to GND)
  D10    -> First display selection
  D11    -> Second display selection
  D12    -> DHT sensor data
  A0     -> Photoresistor output

  Display: Common anode
******************************************************************/

#include <Arduino.h>
#include <math.h>

// Set sensor type:
// 11 = DHT11
// 22 = DHT22
#define DHT_TYPE 11

#define DHT_PIN 12
#define BUTTON_PIN 9

// Variables
int licznik = 0;
int liczba = 0;

int minimum, maksimum;
int jasnosc = 0;
int wilgotnosc = 0;
int temperatura = 0;

char tryb = 'L';

unsigned long lastDHTRead = 0;

// Display pins: a, b, c, d, e, f, g
const byte segmentPins[7] = {
  2, 3, 4, 5, 6, 7, 8
};

// Digit patterns
const byte cyfry[10] = {
  0b00111111, // 0
  0b00000110, // 1
  0b01011011, // 2
  0b01001111, // 3
  0b01100110, // 4
  0b01101101, // 5
  0b01111101, // 6
  0b00000111, // 7
  0b01111111, // 8
  0b01101111  // 9
};

// ----------------------------------------------------
// DHT SENSOR - NO EXTERNAL LIBRARY
// ----------------------------------------------------

bool readDHT(float &humidity, float &temperature) {

  byte data[5] = {0, 0, 0, 0, 0};

  // Send start signal
  pinMode(DHT_PIN, OUTPUT);
  digitalWrite(DHT_PIN, LOW);

#if DHT_TYPE == 11
  delay(20);
#else
  delay(2);
#endif

  digitalWrite(DHT_PIN, HIGH);
  delayMicroseconds(30);

  pinMode(DHT_PIN, INPUT_PULLUP);

  // Sensor response
  if (pulseIn(DHT_PIN, LOW, 120) == 0)
    return false;

  if (pulseIn(DHT_PIN, HIGH, 120) == 0)
    return false;

  // Read 40 bits
  for (int i = 0; i < 40; i++) {

    if (pulseIn(DHT_PIN, LOW, 100) == 0)
      return false;

    unsigned long highTime = pulseIn(DHT_PIN, HIGH, 120);

    if (highTime == 0)
      return false;

    data[i / 8] <<= 1;

    if (highTime > 40)
      data[i / 8] |= 1;
  }

  // Check checksum
  byte checksum = data[0] + data[1] + data[2] + data[3];

  if (checksum != data[4])
    return false;

  // Convert readings
#if DHT_TYPE == 11

  humidity = data[0] + data[1] * 0.1;

  temperature = data[2] + data[3] * 0.1;

#else

  humidity = ((data[0] << 8) | data[1]) * 0.1;

  int16_t rawTemperature =
    ((data[2] & 0x7F) << 8) | data[3];

  temperature = rawTemperature * 0.1;

  if (data[2] & 0x80)
    temperature = -temperature;

#endif

  return true;
}

// ----------------------------------------------------
// DISPLAY DIGIT
// ----------------------------------------------------

void Znak(int iNumer) {

  if (iNumer < 0 || iNumer > 9)
    iNumer = 0;

  byte pattern = cyfry[iNumer];

  for (int i = 0; i < 7; i++) {

    digitalWrite(
      segmentPins[i],
      (pattern & (1 << i)) ? LOW : HIGH
    );
  }
}

// ----------------------------------------------------
// DISPLAY NUMBER
// ----------------------------------------------------

void wyswietl() {

  // Units
  digitalWrite(11, LOW);

  Znak(liczba % 10);

  digitalWrite(10, HIGH);
  delay(2);
  digitalWrite(10, LOW);

  // Tens
  Znak((liczba / 10) % 10);

  digitalWrite(11, HIGH);
  delay(2);
  digitalWrite(11, LOW);
}

// ----------------------------------------------------
// SETUP
// ----------------------------------------------------

void setup() {

  for (int i = 2; i <= 8; i++) {
    pinMode(i, OUTPUT);
    digitalWrite(i, HIGH);
  }

  pinMode(BUTTON_PIN, INPUT_PULLUP);

  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);

  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  pinMode(DHT_PIN, INPUT_PULLUP);

  delay(1000);

  minimum = analogRead(A0);
  maksimum = minimum;

  float h, t;

  if (readDHT(h, t)) {
    wilgotnosc = (int)h;
    temperatura = (int)t;
  }

  lastDHTRead = millis();
}

// ----------------------------------------------------
// MAIN LOOP
// ----------------------------------------------------

void loop() {

  // Refresh display continuously
  wyswietl();

  // Update light measurement
  if (licznik++ > 100) {

    jasnosc = analogRead(A0);

    if (minimum > jasnosc)
      minimum = jasnosc;

    if (maksimum < jasnosc)
      maksimum = jasnosc;

    if (minimum != maksimum) {

      jasnosc = 99L * (jasnosc - minimum)
                / (maksimum - minimum);

    } else {

      jasnosc = 0;
    }

    jasnosc = constrain(jasnosc, 0, 99);

    licznik = 0;
  }

  // Read DHT every 2 seconds
  if (millis() - lastDHTRead >= 2000) {

    lastDHTRead = millis();

    float h, t;

    if (readDHT(h, t)) {

      wilgotnosc = constrain((int)h, 0, 99);

      temperatura = constrain((int)t, 0, 99);
    }
  }

  // Select displayed value
  switch (tryb) {

    case 'L':
      liczba = jasnosc;
      break;

    case 'H':
      liczba = wilgotnosc;
      break;

    case 'T':
      liczba = temperatura;
      break;
  }

  // Button handling
  if (digitalRead(BUTTON_PIN) == LOW) {

    delay(40);

    if (digitalRead(BUTTON_PIN) == LOW) {

      digitalWrite(10, LOW);
      digitalWrite(11, LOW);

      if (tryb == 'L')
        tryb = 'H';

      else if (tryb == 'H')
        tryb = 'T';

      else
        tryb = 'L';

      while (digitalRead(BUTTON_PIN) == LOW) {
        wyswietl();
      }
    }
  }
}

